import os
import sys

BACKEND_DIR = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(BACKEND_DIR, "..", "backend"))

from app.forensic.certificate_analyzer import CertificateAnalyzer

cert_hex = ""
der_bytes = bytes.fromhex(cert_hex)

cd = CertificateAnalyzer.parse_der_certificate(der_bytes)
print("Subject:", cd.subject)
print("Issuer:", cd.issuer)
print("Serial:", cd.serial_number)
print("Fingerprint SHA256:", cd.certificate_fingerprint_sha256)
print("Not Before:", cd.not_before)
print("Not After:", cd.not_after)
print("Validity Status:", cd.validity_status)
print("Days until expiry:", cd.days_until_expiry)
print("Public Key Algorithm:", cd.public_key_algorithm)
print("Public Key Bits:", cd.public_key_bits)
print("Signature Algorithm:", cd.signature_algorithm)
print("Self-Issued:", cd.self_issued)
print("Self-Signed:", cd.self_signed)
print("SANs:", cd.san_names)
print("Chain Trust Status:", cd.chain_trust_status)
print("Analysis Limitations:", cd.analysis_limitations)
